"></i> Sellers CSV</button>\r\n <button class=\"btn btn-outline btn-sm\" onclick=\"exportAdminReport('orders')\"><i class=\"fa-solid fa-receipt\"></i> Orders CSV</button>\r\n <button class=\"btn btn-outline btn-sm\" onclick=\"exportAdminReport('revenue')\"><i class=\"fa-solid fa-coins\"></i> Revenue CSV</button>\r\n <button class=\"btn btn-outline btn-sm\" onclick=\"exportAdminReport('disputes')\"><i class=\"fa-solid fa-gavel\"></i> Disputes CSV</button>\r\n </div>\r\n </div>\r\n </div>\r\n\r\n <!-- SELLERS TAB -->\r\n <div id=\"adm-tab-sellers\" class=\"adm-tab hidden\">\r\n <div class=\"flex justify-between items-center mb-3 flex-wrap gap-2\">\r\n <div class=\"flex gap-2 flex-wrap\">\r\n <select id=\"adm-seller-filter\" class=\"form-select\" style=\"width:auto;padding:.4rem .7rem;font-size:.78rem\" onchange=\"loadAdminSellers()\">\r\n <option value=\"all\">All Sellers</option>\r\n <option value=\"paid\">Active Sellers</option>\r\n <option value=\"trial\">Free Access</option>\r\n <option value=\"suspended\">Admin Review</option>\r\n </select>\r\n <input type=\"text\" id=\"adm-seller-search\" class=\"form-input\" placeholder=\"Name / email...\" style=\"width:160px;font-size:.78rem;padding:.4rem .7rem\" oninput=\"filterAdminSellers()\">\r\n </div>\r\n <span class=\"text-xs color-text3\" id=\"adm-seller-count\"> - </span>\r\n </div>\r\n <div id=\"admin-skeleton\"><div class=\"skeleton mb-3\" style=\"height:82px\"></div><div class=\"skeleton mb-3\" style=\"height:82px\"></div><div class=\"skeleton\" style=\"height:82px\"></div></div>\r\n <div id=\"admin-list\" class=\"hidden\"></div>\r\n <div id=\"admin-empty\" class=\"hidden text-center\" style=\"padding:2.5rem\"><p class=\"color-text3\">No sellers found</p></div>\r\n </div>\r\n\r\n <!-- ORDERS TAB -->\r\n <div id=\"adm-tab-orders\" class=\"adm-tab hidden\">\r\n <div class=\"flex justify-between items-center mb-3 flex-wrap gap-2\">\r\n <select id=\"adm-order-filter\" class=\"form-select\" style=\"width:auto;padding:.4rem .7rem;font-size:.78rem\" onchange=\"loadAdminOrders()\">\r\n <option value=\"all\">All Orders</option>\r\n <option value=\"pending\">Pending</option>\r\n <option value=\"confirmed\">Confirmed</option>\r\n <option value=\"shipped\">Collected by BUYSELL</option>\r\n <option value=\"delivered\">Delivered</option>\r\n <option value=\"cancelled\">Cancelled</option>\r\n </select>\r\n <span class=\"text-xs color-text3\" id=\"adm-order-count\"> - </span>\r\n </div>\r\n <div id=\"adm-orders-skeleton\"><div class=\"skeleton mb-3\" style=\"height:110px\"></div><div class=\"skeleton\" style=\"height:110px\"></div></div>\r\n <div id=\"adm-orders-list\" class=\"hidden\"></div>\r\n <div id=\"adm-orders-empty\" class=\"hidden text-center\" style=\"padding:2.5rem\"><p class=\"color-text3\">No orders found</p></div>\r\n </div>\r\n\r\n <!-- DISPUTES TAB -->\r\n <div id=\"adm-tab-disputes\" class=\"adm-tab hidden\">\r\n <div class=\"flex justify-between items-center mb-3 flex-wrap gap-2\">\r\n <h3 style=\"margin:0\">All Disputes</h3>\r\n <button class=\"btn btn-outline btn-sm\" onclick=\"loadAdminDisputes()\"><i class=\"fa-solid fa-sync\"></i> Refresh</button>\r\n </div>\r\n <div id=\"admin-disputes-list\"><div class=\"skeleton\" style=\"height:90px\"></div></div>\r\n </div>\r\n\r\n <!-- WITHDRAWALS TAB -->\r\n <div id=\"adm-tab-withdrawals\" class=\"adm-tab hidden\">\r\n <div class=\"flex justify-between items-center mb-3 flex-wrap gap-2\">\r\n <h3 style=\"margin:0\">Seller Payouts</h3>\r\n <button class=\"btn btn-outline btn-sm\" onclick=\"loadAdminWithdrawals()\"><i class=\"fa-solid fa-sync\"></i> Refresh</button>\r\n </div>\r\n <div id=\"adm-wd-skeleton\"><div class=\"skeleton mb-3\" style=\"height:100px\"></div><div class=\"skeleton\" style=\"height:100px\"></div></div>\r\n <div id=\"adm-wd-list\" class=\"hidden\"></div>\r\n <div id=\"adm-wd-empty\" class=\"hidden text-center\" style=\"padding:3rem\">\r\n <i class=\"fa-solid fa-check-circle\" style=\"font-size:2.5rem;color:var(--green);display:block;margin-bottom:.75rem\"></i>\r\n <p class=\"color-text3\">No pending withdrawals</p>\r\n </div>\r\n  </div>\r\n\r\n  <!-- ONLINE USERS TAB -->\r\n  <div id=\"adm-tab-online\" class=\"adm-tab hidden\">\r\n  <div class=\"flex justify-between items-center mb-3 flex-wrap gap-2\">\r\n  <div>\r\n  <h3 class=\"mb-1\"><i class=\"fa-solid fa-signal color-green\"></i> User Activity</h3>\r\n  <p class=\"text-xs color-text3\">Online status is based on users seen in the last 5 minutes.</p>\r\n  </div>\r\n  <div class=\"flex gap-2 flex-wrap\">\r\n  <span class=\"badge badge-green\" id=\"adm-online-count\">0 online</span>\r\n  <button class=\"btn btn-outline btn-sm\" onclick=\"loadAdminOnlineUsers()\"><i class=\"fa-solid fa-sync\"></i> Refresh</button>\r\n  </div>\r\n  </div>\r\n  <div class=\"table-responsive\">\r\n  <table class=\"table\">\r\n  <thead><tr><th>User</th><th>Role</th><th>Status</th><th>Logins</th><th>Last Login</th><th>Last Seen</th></tr></thead>\r\n  <tbody id=\"adm-online-list\"><tr><td colspan=\"6\" class=\"text-center text-sm color-text3 p-3\">Loading user activity...</td></tr></tbody>\r\n  </table>\r\n  </div>\r\n  </div>\r\n\r\n <!-- KYC VERIFICATION TAB -->\r\n <div id=\"adm-tab-kyc\" class=\"adm-tab hidden\">\n <div class=\"flex justify-between items-center mb-3 flex-wrap gap-2\">\r\n <div class=\"flex gap-2 flex-wrap\">\r\n <select id=\"adm-kyc-filter\" class=\"form-select\" style=\"width:auto;padding:.4rem .7rem;font-size:.78rem\" onchange=\"loadAdminKyc()\">\r\n <option value=\"pending\">Pending Review</option>\r\n <option value=\"approved\">Approved</option>\r\n <option value=\"rejected\">Rejected</option>\r\n <option value=\"all\">All Submissions</option>\r\n </select>\r\n </div>\r\n <button class=\"btn btn-outline btn-sm\" onclick=\"loadAdminKyc()\"><i class=\"fa-solid fa-sync\"></i> Refresh</button>\r\n </div>\r\n <div id=\"adm-kyc-skeleton\"><div class=\"skeleton mb-3\" style=\"height:150px\"></div></div>\r\n <div id=\"adm-kyc-list\" class=\"hidden\" style=\"display:flex;flex-direction:column;gap:1rem\"></div>\r\n <div id=\"adm-kyc-empty\" class=\"hidden text-center\" style=\"padding:3rem\">\r\n <i class=\"fa-solid fa-shield-check\" style=\"font-size:2.5rem;color:var(--green);display:block;margin-bottom:.75rem\"></i>\r\n <p class=\"color-text3\">No pending KYC verifications</p>\r\n </div>\n </div>\n\n <!-- 1688 DROPSHIPPING REQUESTS TAB -->\n <div id=\"adm-tab-dropship-requests\" class=\"adm-tab hidden\">\n <div class=\"card card-pad-lg\">\n <div class=\"flex justify-between items-start gap-3 wrap mb-3\">\n <div>\n <h3 class=\"mb-1\"><i class=\"fa-solid fa-truck-ramp-box color-green\"></i> 1688 Dropshipping Requests</h3>\n <p class=\"text-xs color-text3\">Review seller sourcing requests, update the status, and message the seller from BUYSELL.</p>\n </div>\n <button class=\"btn btn-outline btn-sm\" onclick=\"loadAdminDropshipRequests()\"><i class=\"fa-solid fa-rotate\"></i> Refresh</button>\n </div>\n <div id=\"admin-dropship-requests-list\" class=\"admin-dropship-requests-list\">\n <div class=\"skeleton\" style=\"height:120px;border-radius:12px\"></div>\n </div>\n </div>\n </div>\n\n <!-- BROADCAST TAB -->\n <div id=\"adm-tab-broadcast\" class=\"adm-tab hidden\">\r\n <div class=\"card card-pad-lg\" style=\"max-width:600px\">\r\n <h3 class=\"mb-1\"><i class=\"fa-solid fa-bullhorn color-green\"></i> Send Platform Broadcast</h3>\r\n <p class=\"text-xs color-text3 mb-3\">Send a product digest with recent product images, descriptions, and direct links.</p>\n <div class=\"form-group\">\r\n <label class=\"form-label\">Target Audience</label>\r\n <select id=\"bc-target\" class=\"form-select\">\r\n <option value=\"all\">Everyone</option>\r\n <option value=\"sellers\">Sellers Only</option>\r\n <option value=\"buyers\">Buyers Only</option>\r\n <option value=\"trial\">Free Access Sellers</option>\r\n </select>\r\n </div>\r\n <div class=\"form-group\">\r\n <label class=\"form-label\">Title</label>\n <input type=\"text\" id=\"bc-title\" class=\"form-input\" placeholder=\"e.g., New products just landed\">\n </div>\r\n <div class=\"form-group\">\r\n <label class=\"form-label\">Intro Message</label>\n <textarea id=\"bc-body\" class=\"form-textarea\" rows=\"3\" placeholder=\"Write a short intro. Recent products will be added automatically.\"></textarea>\n</div>\n <div class=\"broadcast-product-preview\" id=\"bc-product-preview\">\n <div class=\"skeleton\" style=\"height:92px;border-radius:12px\"></div>\n </div>\n <div class=\"form-group\">\r\n <label class=\"form-label\">Type</label>\r\n <div class=\"flex gap-2 flex-wrap\">\r\n <label class=\"filter-chip\"><input type=\"radio\" name=\"bc-type\" value=\"info\" checked style=\"display:none\"> Info Info</label>\r\n <label class=\"filter-chip\"><input type=\"radio\" name=\"bc-type\" value=\"success\" style=\"display:none\"> OK Good News</label>\r\n <label class=\"filter-chip\"><input type=\"radio\" name=\"bc-type\" value=\"warn\" style=\"display:none\"> Warning Warning</label>\r\n <label class=\"filter-chip\"><input type=\"radio\" name=\"bc-type\" value=\"error\" style=\"display:none\"> Urgent</label>\r\n </div>\r\n </div>\r\n <button class=\"btn btn-primary btn-full\" onclick=\"sendBroadcast()\"><i class=\"fa-solid fa-paper-plane\"></i> Send Product Broadcast</button>\n <div class=\"divider mt-4 mb-3\"></div>\r\n <h4 class=\"mb-3\">Recent Broadcasts</h4>\r\n  <div id=\"bc-history\"><p class=\"color-text3 text-sm\">None sent yet.</p></div>\r\n  </div>\r\n  </div>\r\n \r\n  <!-- UPCOMING PRODUCTS TAB -->\r\n  <div id=\"adm-tab-upcoming\" class=\"adm-tab hidden\">\r\n  <div class=\"admin-upcoming-grid\">\r\n  <div class=\"card card-pad-lg\">\r\n  <h3 class=\"mb-1\"><i class=\"fa-solid fa-calendar-plus color-green\"></i> Upload Upcoming Product</h3>\r\n  <p class=\"text-xs color-text3 mb-3\">Create official platform previews shown on the buyer portal. Upload pictures and videos in bulk.</p>\r\n  <div class=\"form-group\"><label class=\"form-label\">Product Name <span class=\"req\">*</span></label><input type=\"text\" id=\"up-title\" class=\"form-input\" placeholder=\"e.g., BUYSELL Smart Watch Pro\"></div>\r\n  <div class=\"form-group\"><label class=\"form-label\">Short Description</label><textarea id=\"up-desc\" class=\"form-textarea\" rows=\"3\" placeholder=\"Tell buyers what is coming soon...\"></textarea></div>\r\n  <div class=\"form-grid form-grid-2\">\r\n  <div class=\"form-group\"><label class=\"form-label\">Expected Launch</label><input type=\"date\" id=\"up-launch-date\" class=\"form-input\"></div>\r\n  <div class=\"form-group\"><label class=\"form-label\">Priority</label><input type=\"number\" id=\"up-priority\" class=\"form-input\" value=\"1\" min=\"0\" max=\"99\"></div>\r\n  </div>\r\n  <div class=\"form-group\"><label class=\"form-label\">Pictures <span class=\"req\">*</span></label><input type=\"file\" id=\"up-images\" class=\"form-input\" accept=\"image/*\" multiple><div class=\"text-xs color-text3 mt-1\">Upload up to 10 pictures. First picture becomes the cover.</div></div>\r\n  <div class=\"form-group\"><label class=\"form-label\">Videos</label><input type=\"file\" id=\"up-videos\" class=\"form-input\" accept=\"video/*\" multiple><div class=\"text-xs color-text3 mt-1\">Upload up to 4 preview videos.</div></div>\r\n  <button class=\"btn btn-primary btn-full\" id=\"up-submit-btn\" onclick=\"submitUpcomingProduct()\"><i class=\"fa-solid fa-cloud-arrow-up\"></i> Publish Upcoming Product</button>\r\n  </div>\r\n  <div class=\"card card-pad-lg\">\r\n  <div class=\"flex justify-between items-center mb-3 flex-wrap gap-2\">\r\n  <div>\r\n  <h3 class=\"mb-1\"><i class=\"fa-solid fa-list color-green\"></i> Upcoming Queue</h3>\r\n  <p class=\"text-xs color-text3\">Manage official previews shown to buyers.</p>\r\n  </div>\r\n  <button class=\"btn btn-outline btn-sm\" onclick=\"loadAdminUpcomingProducts()\"><i class=\"fa-solid fa-rotate\"></i> Refresh</button>\r\n  </div>\r\n  <div id=\"admin-upcoming-list\" class=\"admin-upcoming-list\"><div class=\"text-sm color-text3\">Loading...</div></div>\r\n  </div>\r\n  </div>\r\n  </div>\r\n\r\n  <!-- AI ASSISTANT TAB -->\r\n  <div id=\"adm-tab-ai\" class=\"adm-tab hidden\">\r\n  <div class=\"card card-pad-lg\" style=\"max-width:600px\">\r\n  <h3 class=\"mb-1\"><i class=\"fa-solid fa-robot color-green\"></i> Admin AI Assistant</h3>\r\n <p class=\"text-xs color-text3 mb-3\">AI COO with <b>live database access</b> - reads disputes, sellers, orders, and can suspend/approve users on command.</p>\r\n <div id=\"admin-ai-messages\" style=\"height:280px;overflow-y:auto;background:var(--cream);border-radius:var(--radius-sm);border:1px solid var(--border);padding:.88rem;display:flex;flex-direction:column;gap:.58rem;margin-bottom:.75rem\">\r\n <div class=\"cb-msg bot\" style=\"display:flex;gap:.42rem\">\r\n <div class=\"cb-avatar\" style=\"background:var(--green-xlt);color:var(--green);font-size:.76rem;flex-shrink:0;width:28px;height:28px;border-radius:50%;display:flex;align-items:center;justify-content:center\"><i class=\"fa-solid fa-robot\"></i></div>\r\n <div class=\"cb-bubble\" style=\"background:#fff;border:1px solid var(--border);padding:.52rem .82rem;border-radius:14px;font-size:.79rem;line-height:1.5\">Hello Admin! I have <b>live database access</b> to your BUYSELL platform. I can read disputes, check seller statuses, review KYC, and help with account safety decisions.</div>\r\n </div>\r\n </div>\r\n <div style=\"display:flex;gap:.5rem;flex-wrap:wrap;margin-bottom:.65rem\">\r\n <button class=\"cb-quick-btn\" onclick=\"askAdminBot('Read all open disputes and give me a summary with recommendations')\"><i class=\"fa-solid fa-scale-balanced\"></i> Read Disputes</button>\r\n <button class=\"cb-quick-btn\" onclick=\"askAdminBot('Show me sellers that need account review')\"><i class=\"fa-solid fa-user-shield\"></i> Account Review</button>\r\n <button class=\"cb-quick-btn\" onclick=\"askAdminBot('Summarise pending KYC and account safety issues')\"><i class=\"fa-solid fa-shield-halved\"></i> Safety Review</button>\r\n <button class=\"cb-quick-btn\" onclick=\"askAdminBot('Suggest improvements to complete the marketplace experience')\"><i class=\"fa-solid fa-wand-magic-sparkles\"></i> Site Improvements</button>\r\n <button class=\"cb-quick-btn\" onclick=\"askAdminBot('Summarise platform performance this month')\">\" Performance</button>\r\n <button class=\"cb-quick-btn\" onclick=\"askAdminBot('Give me 5 growth strategies for BUYSELL Nigeria')\"> Growth</button>\r\n </div>\r\n <div style=\"display:flex;gap:.5rem\">\r\n <input type=\"text\" id=\"admin-ai-input\" class=\"form-input\" placeholder=\"Ask anything about your platform...\" onkeypress=\"if(event.key==='Enter')askAdminBot()\">\r\n <button class=\"btn btn-primary\" onclick=\"askAdminBot()\" style=\"flex-shrink:0\"><i class=\"fa-solid fa-paper-plane\"></i></button>\r\n </div>\r\n </div>\r\n </div>\r\n\r\n <!-- RECEIPTS TAB -->\r\n <div id=\"adm-tab-receipts\" class=\"adm-tab hidden\">\r\n <h2 class=\"mb-1\"><i class=\"fa-solid fa-file-invoice color-green\"></i> Legacy Receipts</h2>\r\n <p class=\"color-text3 text-sm mb-3\">Review older seller receipts if they were submitted before seller access became free.</p>\r\n <div class=\"stats-grid mb-4\" style=\"grid-template-columns:repeat(3,1fr)\">\r\n <div class=\"stat-card\"><div class=\"stat-value color-gold\" id=\"rcpt-pending\">0</div><div class=\"stat-label\">Pending</div></div>\r\n <div class=\"stat-card\"><div class=\"stat-value color-green\" id=\"rcpt-approved\">0</div><div class=\"stat-label\">Approved</div></div>\r\n <div class=\"stat-card\"><div class=\"stat-value color-red\" id=\"rcpt-rejected\">0</div><div class=\"stat-label\">Rejected</div></div>\r\n </div>\r\n <div class=\"card overflow-hidden\">\r\n <div class=\"overflow-x\">\r\n <table class=\"data-table\">\r\n <thead><tr>\r\n <th>Seller</th><th>Date</th><th>Reference</th><th>Receipt</th><th>Status</th><th>Actions</th>\r\n </tr></thead>\r\n <tbody id=\"rcpt-table-body\">\r\n <tr><td colspan=\"6\" style=\"text-align:center;padding:2rem;color:var(--text3)\">No receipts submitted yet</td></tr>\r\n </tbody>\r\n </table>\r\n </div>\r\n </div>\r\n </div>\r\n\r\n <!-- PREDICTIVE TAB -->\r\n <div id=\"adm-tab-predictive\" class=\"adm-tab hidden\">\r\n <div class=\"card card-pad mb-3\">\r\n <h3 class=\"mb-1\"><i class=\"fa-solid fa-crystal-ball color-purple\"></i> Predictive Analytics</h3>\r\n <p class=\"text-xs color-text3 mb-3\">AI-powered insights and forecasts for your business.</p>\r\n <div style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:1rem;margin-bottom:1.5rem\">\r\n <div class=\"card card-pad\" style=\"text-align:center\">\r\n <div class=\"text-xs color-text3 mb-1\">Revenue Forecast</div>\r\n <div style=\"font-size:1.3rem;font-weight:800;color:var(--purple)\">Next 30 Days</div>\r\n </div>\r\n <div class=\"card card-pad\" style=\"text-align:center\">\r\n <div class=\"text-xs color-text3 mb-1\">Orders Forecast</div>\r\n <div style=\"font-size:1.3rem;font-weight:800;color:var(--blue)\">Projected</div>\r\n </div>\r\n <div class=\"card card-pad\" style=\"text-align:center\">\r\n <div class=\"text-xs color-text3 mb-1\">Risk Level</div>\r\n <div style=\"font-size:1.3rem;font-weight:800\" id=\"p-risk-level\">Low</div>\r\n </div>\r\n </div>\r\n <div id=\"predictive-analytics\"></div>\r\n <div class=\"mt-3\">\r\n <h4 class=\"mb-2\">\" Trend Analysis</h4>\r\n <div id=\"trend-analysis\"></div>\r\n </div>\r\n <div class=\"mt-3\">\r\n <h4 class=\"mb-2\">' Customer Segments</h4>\r\n <div id=\"customer-segments\"></div>\r\n </div>\r\n </div>\r\n </div>\r\n\r\n <!-- COMPETITORS TAB -->\r\n <div id=\"adm-tab-competitors\" class=\"adm-tab hidden\">\r\n <div class=\"card card-pad mb-3\">\r\n <h3 class=\"mb-1\"><i class=\"fa-solid fa-users color-purple\"></i> Competitor Analysis</h3>\r\n <p class=\"text-xs color-text3 mb-3\">See how you rank against other sellers.</p>\r\n <div id=\"competitor-analysis\"></div>\r\n </div>\r\n <div class=\"card card-pad\">\r\n <h3 class=\"mb-1\"><i class=\"fa-solid fa-tag color-green\"></i> Price Intelligence</h3>\r\n <p class=\"text-xs color-text3 mb-3\">Compare your prices with competitors.</p>\r\n <div id=\"price-intelligence\"></div>\r\n </div>\r\n </div>\r\n\r\n <!-- ACCOUNTS TAB -->\r\n <div id=\"adm-tab-accounts\" class=\"adm-tab hidden\">\r\n <div class=\"flex justify-between items-center mb-3 flex-wrap gap-2\">\r\n <h3 style=\"margin:0\">Account Management</h3>\r\n <button class=\"btn btn-outline btn-sm\" onclick=\"loadAdminAccounts()\"><i class=\"fa-solid fa-sync\"></i> Refresh All</button>\r\n </div>\r\n \r\n <!-- Section 1: Commission Activations -->\r\n <div class=\"card card-pad mb-4\">\r\n <h3 class=\"mb-3\"><i class=\"fa-solid fa-file-invoice color-green\"></i> Legacy Receipts</h3>\r\n <p class=\"text-xs color-text3 mb-3\">Older payment receipts retained for record keeping. Seller access no longer depends on payment approval.</p>\r\n <div class=\"overflow-x\">\r\n <table class=\"data-table\">\r\n <thead><tr><th>Seller</th><th>Date</th><th>Reference</th><th>Receipt</th><th>Action</th></tr></thead>\r\n <tbody id=\"acct-comm-list\"><tr><td colspan=\"5\" class=\"text-center text-sm color-text3 p-3\">Loading...</td></tr></tbody>\r\n </table>\r\n </div>\r\n </div>\r\n\r\n <!-- Section 2: Ad Approvals -->\r\n <div class=\"card card-pad mb-4\">\r\n <h3 class=\"mb-3\"><i class=\"fa-solid fa-bullseye color-blue\"></i> Ad Payment Approvals</h3>\r\n <p class=\"text-xs color-text3 mb-3\">Pending advertisements waiting for payment verification and approval.</p>\r\n <div class=\"overflow-x\">\r\n <table class=\"data-table\">\r\n <thead><tr><th>Advertiser</th><th>Ad Title</th><th>Reference</th><th>Receipt / Media</th><th>Action</th></tr></thead>\r\n <tbody id=\"acct-ads-list\"><tr><td colspan=\"5\" class=\"text-center text-sm color-text3 p-3\">Loading...</td></tr></tbody>\r\n </table>\r\n </div>\r\n </div>\r\n\r\n <!-- Section 3: Trial Extensions -->\r\n <div class=\"card card-pad mb-4\">\r\n <h3 class=\"mb-3\"><i class=\"fa-solid fa-user-shield color-gold\"></i> Seller Access Review</h3>\r\n <p class=\"text-xs color-text3 mb-3\">Seller access is free. Use this area only to review, reactivate, or pause accounts for admin reasons.</p>\r\n <div class=\"flex gap-2 mb-3\">\r\n <input type=\"text\" id=\"acct-trial-search\" class=\"form-input\" placeholder=\"Search seller...\" style=\"width:200px\" oninput=\"filterTrialExtensions()\">\r\n </div>\r\n <div class=\"overflow-x\" style=\"max-height:400px;overflow-y:auto\">\r\n <table class=\"data-table\" style=\"position:relative\">\r\n <thead style=\"position:sticky;top:0;background:#fff;z-index:10;box-shadow:0 1px 2px rgba(0,0,0,0.05)\"><tr><th>Seller</th><th>Email</th><th>Access</th><th>Status</th><th>Action</th></tr></thead>\r\n <tbody id=\"acct-trials-list\"><tr><td colspan=\"5\" class=\"text-center text-sm color-text3 p-3\">Loading...</td></tr></tbody>\r\n </table>\r\n </div>\r\n </div>\r\n </div>\r\n\r\n <!-- NOTIFICATIONS TAB -->\r\n <div id=\"adm-tab-notifications\" class=\"adm-tab hidden\">\r\n <div id=\"notification-settings\"></div>\r\n <div class=\"card card-pad mt-3\">\r\n <h3 class=\"mb-2\"><i class=\"fa-solid fa-bell color-gold\"></i> Browser Notifications</h3>\r\n <p class=\"text-xs color-text3 mb-3\">Enable push notifications in your browser.</p>\r\n <button class=\"btn btn-primary\" onclick=\"requestNotificationPermission()\"><i class=\"fa-solid fa-bell\"></i> Enable Notifications</button>\r\n <button class=\"btn btn-outline ml-2\" onclick=\"testNotification()\">Test</button>\r\n </div>\r\n </div>\r\n\r\n <!-- BRANDING TAB -->\r\n <div id=\"adm-tab-branding\" class=\"adm-tab hidden\">\r\n <div class=\"card card-pad-lg\" style=\"max-width:500px\">\r\n <h3 class=\"mb-1\"><i class=\"fa-solid fa-paint-brush color-green\"></i> Platform Branding</h3>\r\n <p class=\"text-xs color-text3 mb-3\">Update the main logo across the entire marketplace.</p>\r\n <div class=\"form-group\">\r\n <label class=\"form-label\">Upload New Logo</label>\r\n <div class=\"upload-zone\" id=\"logo-zone\" onclick=\"document.getElementById('logo-upload').click()\">\r\n <i class=\"fa-solid fa-cloud-upload-alt\"></i>\r\n <div class=\"upload-label\">Click to select logo</div>\r\n <div class=\"upload-sub\">PNG, JPG, or SVG (Transparent background recommended)</div>\r\n </div>\r\n <input type=\"file\" id=\"logo-upload\" accept=\"image/*\" class=\"hidden\" onchange=\"previewAdminLogo(this)\">\r\n </div>\r\n <div id=\"logo-preview-container\" class=\"hidden mb-3 text-center\">\r\n <p class=\"form-label\">Preview:</p>\r\n <img id=\"logo-preview-img\" src=\"\" style=\"width:64px;height:64px;border-radius:12px;object-fit:contain;border:1px solid var(--border);padding:4px;background:var(--cream);\">\r\n </div>\r\n <button class=\"btn btn-primary btn-full\" id=\"save-logo-btn\" onclick=\"saveAdminLogo()\">\r\n <i class=\"fa-solid fa-save\"></i> Save & Apply Logo\r\n </button>\r\n </div>\r\n </div>\r\n\r\n </div>\r\n </div>\r\n </div>\r\n</div>\r\n\r\n<!-- ==================== SERVICE PROVIDER DASH ====================\r\n<div id=\"service-provider-view\" style=\"display:none;min-height:100vh;background:var(--cream);\">\r\n <div class=\"dash-layout\">\r\n <aside class=\"dash-sidebar\" id=\"spd-sidebar\">\r\n <div class=\"dash-sidebar-head\">\r\n <div style=\"display:flex;justify-content:space-between;align-items:center\">\r\n <div class=\"brand-text\" style=\"font-size:1.05rem;color:#fff\">BUY<span style=\"color:var(--gold)\">SELL</span></div>\r\n </div>\r\n <div class=\"sub\">Service Provider</div>\r\n </div>\r\n <div class=\"dash-user-card\" style=\"padding:.75rem .6rem;border-bottom:1px solid rgba(255,255,255,.06)\">\r\n <div class=\"nav-avatar\" style=\"border-radius:12px;background:var(--purple);color:#fff;flex-shrink:0\"><i class=\"fa-solid fa-tools\"></i></div>\r\n <div>\r\n <div class=\"u-name\" id=\"spd-user-name\">Service Pro</div>\r\n <div class=\"u-email\" id=\"spd-user-email\"> - </div>\r\n </div>\r\n </div>\r\n <div style=\"padding:.5rem .6rem;border-bottom:1px solid rgba(255,255,255,.06)\">\r\n <span id=\"spd-comm-badge\" class=\"badge badge-gold\" style=\"font-size:.65rem;width:100%;text-align:center;display:block\">Trial</span>\r\n </div>\r\n <nav class=\"dash-nav\">\r\n <div class=\"dash-nav-section\">\r\n <div class=\"dash-nav-label\">Workspace</div>\r\n <button class=\"dash-nav-item active\" id=\"spd-nav-overview\" onclick=\"showSpdDash('overview')\"><i class=\"fa-solid fa-chart-pie\"></i> Overview</button>\r\n <button class=\"dash-nav-item\" id=\"spd-nav-portfolio\" onclick=\"showSpdDash('portfolio')\"><i class=\"fa-solid fa-briefcase\"></i> My Portfolio</button>\r\n <button class=\"dash-nav-item\" id=\"spd-nav-bookings\" onclick=\"showSpdDash('bookings')\" style=\"position:relative\"><i class=\"fa-solid fa-calendar-check\"></i> Bookings <span id=\"spd-bookings-badge\" class=\"badge badge-red hidden\" style=\"position:absolute;right:.5rem;top:50%;transform:translateY(-50%);font-size:.6rem;padding:.15rem .4rem\">0</span></button>\r\n <button class=\"dash-nav-item\" id=\"spd-nav-earnings\" onclick=\"showSpdDash('earnings')\"><i class=\"fa-solid fa-coins\"></i> Earnings</button>\r\n <button class=\"dash-nav-item\" id=\"spd-nav-leads\" onclick=\"showSpdDash('leads')\"><i class=\"fa-solid fa-envelope\"></i> Leads & Messages</button>\r\n <button class=\"dash-nav-item\" id=\"spd-nav-reviews\" onclick=\"showSpdDash('reviews')\"><i class=\"fa-solid fa-star\"></i> Reviews</button>\r\n </div>\r\n <div class=\"dash-nav-section\">\r\n <div class=\"dash-nav-label\">Account</div>\r\n <button class=\"dash-nav-item\" id=\"spd-nav-settings\" onclick=\"showSpdDash('settings')\"><i class=\"fa-solid fa-cog\"></i> Profile Settings</button>\r\n <div class=\"dash-logout\" onclick=\"logoutUser()\"><i class=\"fa-solid fa-sign-out-alt\"></i> Sign Out</div>\r\n </div>\r\n </nav>\r\n </aside>\r\n <main class=\"dash-main\">\r\n <div class=\"flex items-center justify-between mb-4 flex-wrap gap-3\">\r\n <div>\r\n <h1 class=\"dash-page-title\">Service Dashboard</h1>\r\n <p class=\"dash-page-sub\">Manage your gig portfolio and connect with local buyers.</p>\r\n </div>\r\n <button class=\"btn btn-primary\" onclick=\"showSpdDash('portfolio')\"><i class=\"fa-solid fa-plus\"></i> Add Service</button>\r\n </div>\r\n <div id=\"spd-sec-overview\" class=\"spd-section\">\r\n <div class=\"stats-grid mb-4\">\r\n <div class=\"stat-card\">\r\n <div class=\"stat-top\"><div class=\"stat-icon\" style=\"background:#dbeafe\"><i class=\"fa-solid fa-eye\" style=\"color:var(--blue)\"></i></div></div>\r\n <div class=\"stat-value\" id=\"spd-views\">0</div><div class=\"stat-label\">Profile Views</div>\r\n </div>\r\n <div class=\"stat-card\">\r\n <div class=\"stat-top\"><div class=\"stat-icon\" style=\"background:#dcfce7\"><i class=\"fa-brands fa-whatsapp\" style=\"color:#25D366\"></i></div></div>\r\n <div class=\"stat-value\" id=\"spd-leads\">0</div><div class=\"stat-label\">WhatsApp Leads</div>\r\n </div>\r\n <div class=\"stat-card\">\r\n <div class=\"stat-top\"><div class=\"stat-icon\" style=\"background:#ede9fe\"><i class=\"fa-solid fa-briefcase\" style=\"color:var(--purple)\"></i></div></div>\r\n <div class=\"stat-value\" id=\"spd-gigs\">0</div><div class=\"stat-label\">Active Gigs</div>\r\n </div>\r\n </div>\r\n <div class=\"card card-pad mb-4\">\r\n <h3 class=\"mb-3\"><i class=\"fa-solid fa-envelope\"></i> Recent Leads</h3>\r\n <div class=\"empty-state\">\r\n <i class=\"fa-solid fa-inbox\" style=\"font-size:2rem;color:var(--border2);display:block;margin-bottom:.65rem\"></i>\r\n <p class=\"color-text3 text-sm\">No contact inquiries yet. Complete your portfolio to get discovered!</p>\r\n </div>\r\n </div>\r\n <div class=\"card card-pad\">\r\n <h3 class=\"mb-3\"><i class=\"fa-solid fa-lightbulb color-gold\"></i> Tips to Get Hired</h3>\r\n <div style=\"display:flex;flex-direction:column;gap:.55rem\">\r\n <div class=\"flex items-center gap-2\"><div style=\"width:6px;height:6px;border-radius:50%;background:var(--green);flex-shrink:0\"></div><span class=\"text-sm\">Add portfolio samples with photos or videos</span></div>\r\n <div class=\"flex items-center gap-2\"><div style=\"width:6px;height:6px;border-radius:50%;background:var(--green);flex-shrink:0\"></div><span class=\"text-sm\">Set competitive rates for your local area</span></div>\r\n <div class=\"flex items-center gap-2\"><div style=\"width:6px;height:6px;border-radius:50%;background:var(--green);flex-shrink:0\"></div><span class=\"text-sm\">Add a clear WhatsApp number so buyers can reach you</span></div>\r\n <div class=\"flex items-center gap-2\"><div style=\"width:6px;height:6px;border-radius:50%;background:var(--green);flex-shrink:0\"></div><span class=\"text-sm\">Collect reviews from past clients</span></div>\r\n </div>\r\n </div>\r\n </div>\r\n <div id=\"spd-sec-portfolio\" class=\"spd-section hidden\">\r\n <div class=\"card card-pad-lg\" style=\"max-width:600px;margin-bottom:1.25rem\">\r\n <h3 class=\"mb-1\"><i class=\"fa-solid fa-plus-circle color-green\"></i> Post a Service Gig</h3>\r\n <p class=\"text-xs color-text3 mb-3\">Describe your service so buyers can find and hire you.</p>\r\n <div class=\"form-group\"><label class=\"form-label\">Service Title <span class=\"req\">*</span></label><input type=\"text\" id=\"spd-title\" class=\"form-input\" placeholder=\"e.g. Professional Plumber in Ikeja Lagos\"></div>\r\n <div class=\"form-grid form-grid-2\">\r\n <div class=\"form-group\"><label class=\"form-label\">Service Category <span class=\"req\">*</span></label>\r\n <select id=\"spd-category\" class=\"form-select\">\r\n <option>Plumbing</option><option>Electrical</option><option>Carpentry</option>\r\n <option>Painting</option><option>Cleaning</option><option>Photography</option>\r\n <option>Design</option><option>Tailoring</option><option>Catering</option><option>Other</option>\r\n </select>\r\n </div>\r\n <div class=\"form-group\"><label class=\"form-label\">Starting Rate (&#8358;) <span class=\"req\">*</span></label><input type=\"number\" id=\"spd-rate\" class=\"form-input\" placeholder=\"5000\" inputmode=\"numeric\"></div>\r\n </div>\r\n <div class=\"form-group\"><label class=\"form-label\">Location <span class=\"req\">*</span></label><input type=\"text\" id=\"spd-location\" class=\"form-input\" placeholder=\"e.g., Ikeja, Lagos\"></div>\r\n <div class=\"form-group\"><label class=\"form-label\">Description <span class=\"req\">*</span></label><textarea id=\"spd-desc\" class=\"form-textarea\" rows=\"3\" placeholder=\"Describe your experience, skills, and what makes you the best choice...\"></textarea></div>\r\n <div class=\"form-group\"><label class=\"form-label\">WhatsApp Number <span class=\"req\">*</span></label><input type=\"tel\" id=\"spd-wa\" class=\"form-input\" placeholder=\"0801 234 5678\" inputmode=\"tel\"></div>\r\n <div class=\"form-group\">\r\n <label class=\"form-label\"><i class=\"fa-solid fa-images\" style=\"color:var(--purple)\"></i> Portfolio Images <span class=\"text-xs color-text3\">(up to 4 images)</span></label>\r\n <input type=\"file\" id=\"spd-images\" accept=\"image/*\" multiple class=\"form-input\" style=\"padding:.5rem\">\r\n <div id=\"spd-img-preview\" style=\"display:flex;gap:.5rem;flex-wrap:wrap;margin-top:.5rem\"></div>\r\n </div>\r\n <button class=\"btn btn-primary btn-full\" onclick=\"publishServiceGig()\"><i class=\"fa-solid fa-paper-plane\"></i> Publish Service Profile</button>\r\n </div>\r\n <div class=\"card card-pad\">\r\n <h3 class=\"mb-3\"><i class=\"fa-solid fa-briefcase\"></i> My Active Gigs</h3>\r\n <div id=\"spd-gigs-list\">\r\n <div class=\"empty-state\">\r\n <i class=\"fa-solid fa-folder-open\" style=\"font-size:2rem;color:var(--border2);display:block;margin-bottom:.65rem\"></i>\r\n <p class=\"color-text3 text-sm\">Your portfolio is empty. Post your first service above!</p>\r\n </div>\r\n </div>\r\n </div>\r\n </div>\r\n <div id=\"spd-sec-bookings\" class=\"spd-section hidden\">\r\n <div class=\"card card-pad\">\r\n <div class=\"flex justify-between items-center mb-3\">\r\n <h3 style=\"margin:0\"><i class=\"fa-solid fa-calendar-check\"></i> My Bookings</h3>\r\n <button class=\"btn btn-outline btn-sm\" onclick=\"loadProviderBookings()\"><i class=\"fa-solid fa-sync\"></i> Refresh</button>\r\n </div>\r\n <div id=\"spd-bookings-list\">\r\n <div class=\"empty-state\">\r\n <i class=\"fa-solid fa-inbox\" style=\"font-size:2rem;color:var(--border2);display:block;margin-bottom:.65rem\"></i>\r\n <p class=\"color-text3 text-sm\">No bookings yet. Share your services to get hired!</p>\r\n </div>\r\n </div>\r\n </div>\r\n </div>\r\n <div id=\"spd-sec-earnings\" class=\"spd-section hidden\">\r\n <div id=\"spd-earnings-content\">\r\n <div class=\"empty-state\">\r\n <i class=\"fa-solid fa-coins\" style=\"font-size:2rem;color:var(--border2);display:block;margin-bottom:.65rem\"></i>\r\n <p class=\"color-text3 text-sm\">Complete bookings to start earning!</p>\r\n </div>\r\n </div>\r\n </div>\r\n <div id=\"spd-sec-leads\" class=\"spd-section hidden\">\r\n <div class=\"card card-pad\">\r\n <h3 class=\"mb-3\"><i class=\"fa-solid fa-envelope\"></i> Leads & Messages</h3>\r\n <div class=\"empty-state\">\r\n <i class=\"fa-solid fa-inbox\" style=\"font-size:2rem;color:var(--border2);display:block;margin-bottom:.65rem\"></i>\r\n <p class=\"color-text3 text-sm\">No leads yet. Share your profile link to get more visibility.</p>\r\n </div>\r\n </div>\r\n </div>\r\n <div id=\"spd-sec-reviews\" class=\"spd-section hidden\">\r\n <div class=\"card card-pad\">\r\n <h3 class=\"mb-3\"><i class=\"fa-solid fa-star color-gold\"></i> Client Reviews</h3>\r\n <div class=\"empty-state\">\r\n <i class=\"fa-solid fa-star\" style=\"font-size:2rem;color:var(--border2);display:block;margin-bottom:.65rem\"></i>\r\n <p class=\"color-text3 text-sm\">No reviews yet. Start delivering excellent service to get your first review!</p>\r\n </div>\r\n </div>\r\n </div>\r\n <div id=\"spd-sec-settings\" class=\"spd-section hidden\">\r\n <div class=\"card card-pad-lg\" style=\"max-width:600px\">\r\n <h3 class=\"mb-3\"><i class=\"fa-solid fa-cog\"></i> Profile Settings</h3>\r\n <div class=\"form-group\"><label class=\"form-label\">Display Name</label><input type=\"text\" id=\"spd-s-name\" class=\"form-input\" placeholder=\"Your full name\"></div>\r\n <div class=\"form-group\"><label class=\"form-label\">WhatsApp Number</label><input type=\"tel\" id=\"spd-s-wa\" class=\"form-input\" placeholder=\"0801 234 5678\" inputmode=\"tel\"></div>\r\n <div class=\"form-group\"><label class=\"form-label\">Bio / About</label><textarea id=\"spd-s-bio\" class=\"form-textarea\" rows=\"3\" placeholder=\"Tell buyers about yourself...\"></textarea></div>\r\n <button class=\"btn btn-primary btn-full\" onclick=\"saveServiceProfile()\"><i class=\"fa-solid fa-save\"></i> Save Profile</button>\r\n </div>\r\n </div>\r\n </main>\r\n </div>\r\n</div>\r\n-->\r\n\r\n<!-- PWA Install Bar -->\r\n<div id=\"pwa-install-bar\" class=\"hidden\" style=\"position:fixed;bottom:60px;left:50%;transform:translateX(-50%);z-index:999;background:linear-gradient(135deg,var(--forest),#1a3a26);color:#fff;padding:.65rem 1.2rem;border-radius:14px;display:flex;align-items:center;gap:.75rem;box-shadow:0 4px 20px rgba(0,0,0,.3);max-width:380px;width:90%\">\r\n <i class=\"fa-solid fa-mobile-screen\" style=\"font-size:1.3rem;color:var(--gold)\"></i>\r\n <div style=\"flex:1\">\r\n <div style=\"font-weight:700;font-size:.85rem\">Install BUYSELL App</div>\r\n <div style=\"font-size:.7rem;opacity:.7\">Add to home screen for the best experience</div>\r\n </div>\r\n <button onclick=\"installPWA()\" class=\"btn btn-sm\" style=\"background:var(--gold);color:#000;font-weight:700\">Install</button>\r\n <button onclick=\"dismissInstallBar()\" style=\"background:none;border:none;color:rgba(255,255,255,.5);cursor:pointer;font-size:.85rem\"><i class=\"fa-solid fa-times\"></i></button>\r\n</div>\r\n\r\n<!-- Compare Bar (floating) -->\r\n<div id=\"compare-bar\" class=\"hidden\" style=\"position:fixed;bottom:70px;left:50%;transform:translateX(-50%);z-index:998;background:var(--purple);color:#fff;padding:.5rem 1rem;border-radius:12px;display:flex;align-items:center;gap:.75rem;box-shadow:0 4px 16px rgba(0,0,0,.25)\">\r\n <span style=\"font-size:.82rem;font-weight:600\" id=\"compare-count\">0</span><span style=\"font-size:.78rem\"> products selected</span>\r\n <button onclick=\"showCompareModal()\" class=\"btn btn-sm\" style=\"background:#fff;color:var(--purple);font-weight:700\">Compare Now</button>\r\n <button onclick=\"clearCompare()\" style=\"background:none;border:none;color:rgba(255,255,255,.6);cursor:pointer;font-size:.78rem\">Clear</button>\r\n</div>\r\n\r\n<!-- LEFT SIDE: Language Selector (floating) -->\r\n<div style=\"position:fixed;bottom:16px;left:16px;z-index:997\">\r\n <select onchange=\"setLanguage(this.value)\" style=\"font-size:.7rem;padding:.3rem .5rem;border-radius:8px;border:1px solid var(--border);background:#fff;cursor:pointer;box-shadow: 0 2px 8px rgba(0,0,0,0.15);\">\r\n <option value=\"en\">English</option>\r\n <option value=\"pcm\">Pidgin</option>\r\n <option value=\"ha\">Hausa</option>\r\n <option value=\"yo\">Yoruba</option>\r\n <option value=\"ig\">Igbo</option>\r\n </select>\r\n</div>\r\n\r\n\r\n\r\n<!-- ==================== NEW MODALS ==================== -->\r\n\r\n<!-- WISHLIST MODAL -->\r\n<div id=\"wishlist-modal\" class=\"modal-overlay\">\r\n <div class=\"modal-box\" style=\"max-width:480px\"><button class=\"modal-close\" onclick=\"closeModal('wishlist-modal')\"><i class=\"fa-solid fa-times\"></i></button>\r\n <h2 class=\"mb-3\"><i class=\"fa-solid fa-heart\" style=\"color:#ef4444\"></i> My Wishlist</h2>\r\n <div id=\"wishlist-items\"></div>\r\n </div>\r\n</div>\r\n\r\n<!-- COMPARE MODAL -->\r\n<div id=\"compare-modal\" class=\"modal-overlay\">\r\n <div class=\"modal-box\" style=\"max-width:700px;padding:0\"><button class=\"modal-close\" onclick=\"closeModal('compare-modal')\" style=\"z-index:2\"><i class=\"fa-solid fa-times\"></i></button>\r\n <div style=\"padding:1.25rem\">\r\n <h2 class=\"mb-3\"><i class=\"fa-solid fa-code-compare\" style=\"color:var(--purple)\"></i> Product Comparison</h2>\r\n <div id=\"compare-content\" style=\"overflow-x:auto\"></div>\r\n </div>\r\n </div>\r\n</div>\r\n\r\n<!-- INBOX MODAL -->\r\n<div id=\"inbox-modal\" class=\"modal-overlay\">\r\n <div class=\"modal-box inbox-box\"><button class=\"modal-close\" onclick=\"closeModal('inbox-modal')\"><i class=\"fa-solid fa-times\"></i></button>\r\n <div class=\"inbox-head\">\r\n <div>\r\n <h2><i class=\"fa-solid fa-envelope color-green\"></i> Messages</h2>\r\n <p>Buyer and seller conversations</p>\r\n </div>\r\n <button class=\"btn btn-outline btn-sm\" onclick=\"showInbox()\"><i class=\"fa-solid fa-rotate\"></i></button>\r\n </div>\r\n <div id=\"inbox-list\"></div>\r\n </div>\r\n</div>\r\n\r\n<!-- MESSAGE MODAL (Conversation) -->\r\n<div id=\"message-modal\" class=\"modal-overlay\">\r\n <div class=\"modal-box message-box\">\r\n <div class=\"message-head\">\r\n <button class=\"message-back-btn\" onclick=\"closeModal('message-modal');showInbox()\" title=\"Back to inbox\"><i class=\"fa-solid fa-chevron-left\"></i></button>\r\n <div class=\"message-avatar\" id=\"msg-partner-avatar\">U</div>\r\n <div class=\"message-title-wrap\">\r\n <div class=\"font-bold\" id=\"msg-partner-name\">User</div>\r\n <div id=\"msg-partner-meta\">Conversation</div>\r\n </div>\r\n <button onclick=\"closeModal('message-modal')\" class=\"message-close-btn\"><i class=\"fa-solid fa-times\"></i></button>\r\n </div>\r\n <div id=\"msg-product-card\" class=\"msg-product-card hidden\"></div>\r\n <div id=\"msg-conversation\" class=\"msg-conversation\"></div>\r\n <div class=\"msg-quick-row\">\r\n <button type=\"button\" onclick=\"insertQuickMessage('Is this still available?')\">Available?</button>\r\n <button type=\"button\" onclick=\"insertQuickMessage('Can you send more details?')\">More details</button>\r\n <button type=\"button\" onclick=\"insertQuickMessage('What is your best price?')\">Best price</button>\r\n </div>\r\n <div class=\"msg-input-row\">\r\n <input type=\"file\" id=\"msg-image-input\" accept=\"image/*\" style=\"display:none\" onchange=\"handleMessageImageSelect(this)\">\r\n <button type=\"button\" class=\"btn btn-outline msg-attach-btn\" onclick=\"document.getElementById('msg-image-input').click()\" title=\"Send image\"><i class=\"fa-solid fa-image\"></i></button>\r\n <textarea id=\"msg-input\" class=\"form-input\" placeholder=\"Type a message...\" rows=\"1\" onkeydown=\"handleMessageKey(event)\"></textarea>\r\n <button class=\"btn btn-primary\" onclick=\"sendMessage()\" id=\"msg-send-btn\"><i class=\"fa-solid fa-paper-plane\"></i></button>\r\n </div>\r\n <div id=\"msg-image-preview\" class=\"msg-image-preview hidden\"></div>\r\n </div>\r\n</div>\r\n\r\n<!-- ORDER TRACKING MODAL -->\r\n<div id=\"tracking-modal\" class=\"modal-overlay\">\r\n <div class=\"modal-box tracking-box\"><button class=\"modal-close\" onclick=\"closeModal('tracking-modal')\"><i class=\"fa-solid fa-times\"></i></button>\r\n <h2 class=\"mb-1\"><i class=\"fa-solid fa-truck color-green\"></i> Order Tracking</h2>\r\n <p class=\"color-text3 text-sm mb-3\">Order: <span class=\"font-bold\" id=\"tracking-order-id\"></span></p>\r\n <div class=\"tracking-status-strip\" id=\"tracking-status-strip\"></div>\r\n <div id=\"tracking-timeline\"></div>\r\n <div id=\"tracking-update-panel\" class=\"tracking-update-panel hidden\">\r\n <div class=\"form-grid form-grid-2\">\r\n <select id=\"tracking-status-input\" class=\"form-select\">\r\n <option value=\"confirmed\">BUYSELL Pickup Scheduled</option>\n <option value=\"picked_up\">Collected by BUYSELL</option>\n <option value=\"in_transit\">With BUYSELL Delivery</option>\n <option value=\"out_for_delivery\">Out for Delivery</option>\r\n <option value=\"delivered\">Delivered</option>\r\n </select>\r\n <input id=\"tracking-note-input\" class=\"form-input\" placeholder=\"Short update note\">\r\n </div>\r\n <button class=\"btn btn-primary btn-full mt-2\" onclick=\"submitTrackingUpdate()\"><i class=\"fa-solid fa-plus\"></i> Add Tracking Update</button>\r\n </div>\r\n </div>\r\n</div>\r\n\r\n<div id=\"kyc-doc-modal\" class=\"modal-overlay\">\r\n <div class=\"modal-box\" style=\"max-width:720px\">\r\n <button class=\"modal-close\" onclick=\"closeModal('kyc-doc-modal')\"><i class=\"fa-solid fa-times\"></i></button>\r\n <div class=\"flex justify-between items-center mb-3 gap-2 flex-wrap\">\r\n <h2 id=\"kyc-doc-title\" style=\"margin:0;font-size:1.05rem\">KYC Document</h2>\r\n <a id=\"kyc-doc-open-link\" href=\"#\" target=\"_blank\" rel=\"noopener\" class=\"btn btn-outline btn-sm\"><i class=\"fa-solid fa-up-right-from-square\"></i> Open Original</a>\r\n </div>\r\n <div style=\"background:var(--cream);border:1px solid var(--border);border-radius:8px;padding:.5rem;max-height:72vh;overflow:auto\">\r\n <img id=\"kyc-doc-img\" src=\"\" alt=\"KYC document\" style=\"width:100%;height:auto;display:block;border-radius:6px\">\r\n </div>\r\n </div>\r\n</div>\r\n\r\n<!-- SERVICE REVIEW MODAL \r\n<div id=\"service-review-modal\" class=\"modal-overlay\">\r\n <div class=\"modal-box\"><button class=\"modal-close\" onclick=\"closeModal('service-review-modal')\"><i class=\"fa-solid fa-times\"></i></button>\r\n <h2 class=\"mb-1\">Rate Service Provider</h2>\r\n <p class=\"color-text3 text-sm mb-3\" id=\"svc-review-provider\"></p>\r\n <input type=\"hidden\" id=\"svc-review-booking-id\">\r\n <div class=\"review-star-row\" id=\"svc-star-row\" style=\"margin-bottom:1rem\">\r\n <button class=\"star-btn\" data-val=\"1\" onclick=\"setSvcRating(1)\">&#9733;</button>\r\n <button class=\"star-btn\" data-val=\"2\" onclick=\"setSvcRating(2)\">&#9733;</button>\r\n <button class=\"star-btn\" data-val=\"3\" onclick=\"setSvcRating(3)\">&#9733;</button>\r\n <button class=\"star-btn\" data-val=\"4\" onclick=\"setSvcRating(4)\">&#9733;</button>\r\n <button class=\"star-btn\" data-val=\"5\" onclick=\"setSvcRating(5)\">&#9733;</button>\r\n </div>\r\n <div class=\"form-group\"><label class=\"form-label\">Your Review</label><textarea id=\"svc-review-text\" class=\"form-textarea\" rows=\"3\" placeholder=\"How was your experience?\"></textarea></div>\r\n <button class=\"btn btn-primary btn-full\" onclick=\"submitServiceReview()\"><i class=\"fa-solid fa-star\"></i> Submit Review</button>\r\n </div>\r\n</div>\r\n-->";
